#include <chrono>
#include <cstdint>
#include <iostream>
#include <string>
#include <algorithm>
#include HEADER
struct Mod {
 std::uint32_t value=0;
 Mod()=default; Mod(std::int64_t x):value(x%998244353){}
 Mod& operator+=(Mod b){value+=b.value;if(value>=998244353)value-=998244353;return *this;}
 Mod& operator-=(Mod b){if(value<b.value)value+=998244353;value-=b.value;return *this;}
 Mod& operator*=(Mod b){value=std::uint64_t(value)*b.value%998244353;return *this;}
 friend bool operator==(Mod,Mod)=default;
};
template<class T> std::uint64_t val(T x){if constexpr(std::is_same_v<T,Mod>)return x.value;else return x;}
template<class T> void run(std::size_t n,int rep,int op){
 std::vector<T> a(n),b(n);for(std::size_t i=0;i<n;++i){a[i]=T((i*17+3)%7);b[i]=T((i*11+2)%7);}
 auto old=a;
 std::uint64_t sum=0;
 auto start=std::chrono::steady_clock::now();
 for(int r=0;r<rep;++r){
  if(op==0){superset_zeta_transform(a);superset_mobius_transform(a);sum+=val(a[r%n]);}
  if(op==1){subset_zeta_transform(a);subset_mobius_transform(a);sum+=val(a[r%n]);}
  if(op==2){auto c=bitwise_and_convolution(a,b);sum+=val(c[r%n]);}
  if(op==3){auto c=bitwise_or_convolution(a,b);sum+=val(c[r%n]);}
 }
 auto end=std::chrono::steady_clock::now();
 if(op<2 && old!=a)std::abort();
 std::cout<<std::chrono::duration<double,std::nano>(end-start).count()/rep<<' '<<sum<<'\n';
}
int main(int argc,char**argv){(void)argc;std::string t=argv[1];auto n=std::stoull(argv[2]);auto rep=std::stoi(argv[3]);int op=std::stoi(argv[4]);if(t=="mod")run<Mod>(n,rep,op);else if(t=="u32")run<std::uint32_t>(n,rep,op);else if(t=="i64")run<std::int64_t>(n,rep,op);}

