#include <cstdint>
#include <random>
#include <iostream>
#include <cassert>
#include <algorithm>
#include HEADER
struct Mod {
 std::uint32_t value=0;
 Mod()=default; Mod(std::int64_t x){x%=998244353;if(x<0)x+=998244353;value=x;}
 Mod& operator+=(Mod b){value+=b.value;if(value>=998244353)value-=998244353;return *this;}
 Mod& operator-=(Mod b){if(value<b.value)value+=998244353;value-=b.value;return *this;}
 Mod& operator*=(Mod b){value=std::uint64_t(value)*b.value%998244353;return *this;}
 friend bool operator==(Mod,Mod)=default;
};
template<class T> T prod(T a,T b){if constexpr(std::is_integral_v<T> && std::is_unsigned_v<T>)return T(std::uint64_t(a)*std::uint64_t(b));else{a*=b;return a;}}
template<class T> void check(){std::mt19937_64 rng(421);for(int k=0;k<7;++k)for(int rep=0;rep<50;++rep){const std::size_t n=std::size_t{1}<<k;std::vector<T>a(n),b(n);for(std::size_t i=0;i<n;++i){if constexpr(std::is_unsigned_v<T>){a[i]=T(rng());b[i]=T(rng());}else{a[i]=T(int(rng()%5)-2);b[i]=T(int(rng()%5)-2);}}
 for(bool subset:{false,true}){
  std::vector<T> z(n),c(n),sq(n);for(std::size_t i=0;i<n;++i){for(std::size_t j=0;j<n;++j){if((subset?(i&j)==j:(i&j)==i))z[i]+=a[j];auto p=prod(a[i],b[j]);c[subset?(i|j):(i&j)]+=p;p=prod(a[i],a[j]);sq[subset?(i|j):(i&j)]+=p;}}
  auto x=a;if(subset)subset_zeta_transform(x);else superset_zeta_transform(x);assert(x==z);if(subset)subset_mobius_transform(x);else superset_mobius_transform(x);assert(x==a);
  auto got=subset?bitwise_or_convolution(a,b):bitwise_and_convolution(a,b);assert(got==c);
#ifdef SQUARE
  auto s=subset?bitwise_or_square(a):bitwise_and_square(a);assert(s==sq);
#endif
 }
}std::vector<T>empty;superset_zeta_transform(empty);subset_mobius_transform(empty);assert(bitwise_and_convolution(empty,empty).empty());}
int main(){check<std::int64_t>();check<std::uint32_t>();check<Mod>();
#ifdef SQUARE
check<std::uint16_t>();check<std::uint8_t>();
#endif
std::cout<<"pass\n";}

