#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <new>
#include <iostream>
#include <utility>
#include <cassert>
#include HEADER
bool count_enabled=false;std::size_t allocations=0,allocated_bytes=0;
void* operator new(std::size_t n){if(void*p=std::malloc(n?n:1)){if(count_enabled){++allocations;allocated_bytes+=n;}return p;}throw std::bad_alloc();}
void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}
void* operator new[](std::size_t n){return ::operator new(n);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
struct Counts{std::size_t allocations,bytes;};
template<class F> Counts counted(F f){allocations=allocated_bytes=0;count_enabled=true;f();count_enabled=false;return {allocations,allocated_bytes};}
int main(){using T=std::uint32_t;std::vector<T>a(256,1),b(256,2),out;const auto olda=a,oldb=b;
 auto emit=[](const char*name,Counts c,std::size_t expected){assert(c.allocations==expected);std::cout<<name<<' '<<c.allocations<<' '<<c.bytes<<'\n';};
 emit("four_transforms",counted([&]{superset_zeta_transform(a);superset_mobius_transform(a);subset_zeta_transform(a);subset_mobius_transform(a);}),0);assert(a==olda);
 emit("and_lvalues",counted([&]{out=bitwise_and_convolution(a,b);}),2);assert(a==olda&&b==oldb);
 emit("or_lvalues",counted([&]{out=bitwise_or_convolution(a,b);}),2);assert(a==olda&&b==oldb);
 a.reserve(512);b.reserve(512);emit("and_moves",counted([&]{out=bitwise_and_convolution(std::move(a),std::move(b));}),0);assert(out.capacity()==512);
 a=olda;b=oldb;emit("or_moves",counted([&]{out=bitwise_or_convolution(std::move(a),std::move(b));}),0);
#ifdef FINAL
 a=olda;emit("and_square_lvalue",counted([&]{out=bitwise_and_square(a);}),1);assert(a==olda);
 emit("or_square_lvalue",counted([&]{out=bitwise_or_square(a);}),1);assert(a==olda);
 a.reserve(512);emit("and_square_move",counted([&]{out=bitwise_and_square(std::move(a));}),0);assert(out.capacity()==512);
 a=olda;emit("or_square_move",counted([&]{out=bitwise_or_square(std::move(a));}),0);
#endif
 std::vector<T>empty;emit("empty_and",counted([&]{out=bitwise_and_convolution(empty,empty);}),0);
}

