from pathlib import Path
p=Path(__file__).parent;b=p.parent/'baseline/Math/Zeta/components'
base=(b/'set_transform.inc').read_text();inc=(p/'baseline.hpp').read_text().split('// 集合変換')[0]
helper='''#ifndef SIRKIT_SET_TRANSFORM_SCALAR_DETAIL_DEFINED
#define SIRKIT_SET_TRANSFORM_SCALAR_DETAIL_DEFINED
namespace reinsirk::detail {
template <bool Subset, bool Subtract, class T>
inline void set_transform_scalar(std::vector<T>& f) {
    const std::size_t n = f.size();
    if (n >= 8) {
        for (std::size_t base = 0; base < n; base += 8) {
            auto add = [&](std::size_t a, std::size_t b) {
                if constexpr (Subtract) f[base + a] -= f[base + b];
                else f[base + a] += f[base + b];
            };
            if constexpr (Subset) {
                add(1, 0); add(3, 2); add(5, 4); add(7, 6);
                add(2, 0); add(3, 1); add(6, 4); add(7, 5);
                add(4, 0); add(5, 1); add(6, 2); add(7, 3);
            } else {
                add(0, 1); add(2, 3); add(4, 5); add(6, 7);
                add(0, 2); add(1, 3); add(4, 6); add(5, 7);
                add(0, 4); add(1, 5); add(2, 6); add(3, 7);
            }
        }
    }
    for (std::size_t half = n >= 8 ? 8 : 1; half < n; half *= 2) {
        for (std::size_t base = 0; base < n; base += half * 2) {
            for (std::size_t j = 0; j < half; ++j) {
                auto& out = f[base + j + (Subset ? half : 0)];
                const auto& in = f[base + j + (Subset ? 0 : half)];
                if constexpr (Subtract) out -= in;
                else out += in;
            }
        }
    }
}
}
#endif

'''
# const auto& input is semantically narrower than original T& for odd operator types.
helper=helper.replace('const auto& in','auto& in')
text=base
for subset in [False,True]:
 for sub in [False,True]:
  lhs='base + half + j' if subset else 'base + j';rhs='base + j' if subset else 'base + half + j';op='-=' if sub else '+='
  old=f'''    for (std::size_t half = 1; half < f.size(); half *= 2) {{
        for (std::size_t base = 0; base < f.size(); base += half * 2) {{
            for (std::size_t j = 0; j < half; ++j) f[{lhs}] {op} f[{rhs}];
        }}
    }}'''
  assert text.count(old)==1;text=text.replace(old,'    reinsirk::detail::set_transform_scalar<'+str(subset).lower()+', '+str(sub).lower()+'>(f);')
text=helper+text
conv=(b/'bitwise_convolution.inc').read_text();multi='''#ifndef SIRKIT_BITWISE_MULTIPLY_DETAIL_DEFINED
#define SIRKIT_BITWISE_MULTIPLY_DETAIL_DEFINED
namespace reinsirk::detail {
template <class T> inline void bitwise_multiply_assign(T& left, T& right) {
    if constexpr (std::is_unsigned_v<T> && sizeof(T) < sizeof(unsigned int))
        left = static_cast<T>(static_cast<unsigned int>(left) * static_cast<unsigned int>(right));
    else left *= right;
}
}
#endif

'''
conv=multi+conv.replace('f[i] *= g[i]','reinsirk::detail::bitwise_multiply_assign(f[i], g[i])')
for name,prefix in [('and','superset'),('or','subset')]:
 guard='SIRKIT_BITWISE_'+name.upper()+'_SQUARE_DEFINED'
 conv+=f'''// bitwise_{name}_square(f): h[k]=sum_{{i{('&' if name=='and' else '|')}j=k}}f[i]f[j]。長さ2^k、O(n log n)、変換2回。
#ifndef {guard}
#define {guard}
template <class T> std::vector<T> bitwise_{name}_square(std::vector<T> f) {{
    {prefix}_zeta_transform(f);
    for (std::size_t i = 0; i < f.size(); ++i)
        reinsirk::detail::bitwise_multiply_assign(f[i], f[i]);
    {prefix}_mobius_transform(f);
    return f;
}}
#endif

'''
(p/'proposal_set_transform.inc').write_text(text);(p/'proposal_bitwise_convolution.inc').write_text(conv)
(p/'helper.hpp').write_text(inc+text+conv)

